export const ANGLES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Sudut sebagai bukaan antara dua garis",q:"Saat kamu membuka pintu sebagian, celah antara pintu dan dinding membentuk bentuk apa?",options:["Sebuah sudut","Sebuah lingkaran sempurna","Garis lurus"],answer:0,explain:"Celah antara dua garis yang bertemu di satu titik (seperti pintu dan dinding tempatnya berengsel) disebut sudut.",hint:"Apakah bukaan antara pintu dan dinding bertemu di satu titik bersama, membentuk bentuk sudut?"},
{n:2,type:"mcq",micro:"Sudut siku-siku konkret (sudut buku)",q:"Sudut halaman buku persegi panjang membentuk sudut yang terlihat persis persegi. Jenis sudut apa ini disebut?",options:["Sudut tumpul","Sudut siku-siku","Sudut refleks"],answer:1,explain:"Sudut yang terlihat persis persegi, seperti sudut halaman buku, disebut sudut siku-siku (90°).",hint:"Sudut yang 'terlihat persis persegi,' seperti sudut selembar kertas, memiliki nama khusus."},
{n:3,type:"tf",micro:"Sudut tentang rotasi/bukaan, bukan panjang",q:"Benar atau Salah: Sudut mengukur seberapa banyak 'bukaan' atau 'putaran' antara dua garis yang bertemu di satu titik, bukan panjang garis itu sendiri.",answer:true,explain:"Sudut menggambarkan jumlah putaran atau bukaan antara dua garis pada titik yang sama, terlepas dari seberapa panjang garis-garis itu digambar.",hint:"Apakah membuat kedua garis sudut lebih panjang atau pendek mengubah seberapa 'terbuka' sudut itu terlihat?"},
{n:4,type:"mcq",micro:"Sudut konkret (jarum jam)",q:"Pada pukul 3:00, jarum jam dan jarum menit sebuah jam membentuk sesuatu yang terlihat seperti sudut persegi sempurna. Jenis sudut apa ini?",options:["Sudut refleks","Sudut lurus","Sudut siku-siku"],answer:2,explain:"Pada pukul 3:00, jarum jam membentuk sudut siku-siku (90°), seperti sudut persegi.",hint:"Apakah bentuk yang dibentuk jarum jam pada pukul 3:00 terlihat seperti sudut buku yang persegi?"},
{n:5,type:"mcq",micro:"Sudut konkret (gunting)",q:"Saat kamu membuka sepasang gunting sangat lebar, hampir sepenuhnya rata, seperti apa sudut antara kedua bilahnya mulai terlihat?",options:["Hampir seperti titik kecil tanpa bukaan","Hampir seperti garis lurus rata penuh","Tepat sudut siku-siku 90°"],answer:1,explain:"Membuka gunting sangat lebar membuat sudut antara kedua bilahnya mendekati garis lurus (180°).",hint:"Jika kamu terus membuka gunting itu lebih lebar dan lebih lebar, bentuk apa yang akhirnya akan terlihat oleh kedua bilah itu bersama?"},
{n:6,type:"mcq",micro:"Perbandingan sudut konkret",q:"Sudut A terlihat seperti sudut sempit dan tajam (seperti ujung sepotong pizza). Sudut B terlihat seperti sudut lebar dan terbuka (seperti buku yang dibuka hampir rata). Sudut mana yang lebih besar?",options:["Sudut B","Sudut A","Keduanya persis sama"],answer:0,explain:"Sudut yang lebar dan terbuka mewakili sudut yang lebih besar (lebih banyak putaran/bukaan) daripada sudut sempit dan tajam.",hint:"Sudut mana yang menunjukkan LEBIH BANYAK putaran atau bukaan antara kedua sisinya?"},
{n:7,type:"tf",micro:"Garis lurus membentuk sudut lurus",q:"Benar atau Salah: Sebuah garis yang persis lurus juga bisa dianggap sebagai jenis sudut khusus yang disebut 'sudut lurus.'",answer:true,explain:"Sebuah garis lurus mewakili 'sudut lurus,' berukuran tepat 180°.",hint:"Bisakah garis lurus yang benar-benar rata dianggap sebagai 'sudut' yang sepenuhnya terbuka?"},
{n:8,type:"mcq",micro:"Sudut konkret (tanjakan/kemiringan)",q:"Sebuah tanjakan kursi roda yang naik sangat landai (sudut kecil dan sempit dari tanah) umumnya dianggap lebih aman daripada tanjakan yang naik sangat curam (sudut besar dari tanah). Mengapa?",options:["Sudut yang lebih landai berarti tanjakannya lebih panjang, yang tidak relevan dengan keamanan","Ukuran sudut tidak ada hubungan nyata dengan seberapa curam atau aman sebuah tanjakan terasa","Sudut yang lebih landai (lebih kecil) berarti kemiringan yang kurang curam untuk dilalui naik atau turun"],answer:2,explain:"Sudut yang lebih kecil antara tanjakan dan tanah berarti kemiringan yang lebih landai dan kurang curam, yang umumnya lebih aman dan lebih mudah dilalui.",hint:"Apakah sudut yang lebih kecil dari tanah menciptakan kemiringan yang lebih landai, atau lebih curam?"},
{n:9,type:"mcq",micro:"Sudut konkret (tutup laptop)",q:"Saat kamu membuka tutup laptop hanya sedikit, sudut antara layar dan alas keyboard kecil. Saat kamu membukanya lebih lanjut menuju rata, apa yang terjadi pada sudutnya?",options:["Sudutnya membesar","Sudutnya hilang sepenuhnya","Sudutnya mengecil"],answer:0,explain:"Membuka tutup laptop lebih lanjut meningkatkan jumlah 'putaran' antara layar dan alasnya, membuat sudutnya lebih besar.",hint:"Apakah membuka sesuatu LEBIH LEBAR meningkatkan atau menurunkan sudut antara kedua bagiannya?"},
{n:10,type:"mcq",micro:"Sudut konkret (putaran penuh / lingkaran)",q:"Jika kamu berputar sepenuhnya dalam satu lingkaran penuh, kembali persis ke arah awalmu menghadap, berapa banyak putaran (sudut) yang telah kamu buat?",options:["Seperempat putaran (90°)","Setengah putaran","Putaran penuh 360°"],answer:2,explain:"Berputar lengkap kembali ke arah awalmu adalah putaran penuh 360°, rotasi tunggal terbesar yang mungkin.",hint:"Apakah berputar sepenuhnya kembali ke posisi awalmu mewakili nilai putaran satu lingkaran penuh?"},
{n:11,type:"mcq",micro:"Identifikasi sudut konkret (seperempat putaran)",q:"Jika kamu menghadap ke depan lalu berbalik menghadap persis ke kananmu (seperempat dari putaran penuh), jenis sudut apa yang telah kamu lalui?",options:["Sudut lurus (180°)","Sudut siku-siku (90°)","Sudut refleks"],answer:1,explain:"Seperempat dari putaran penuh 360° adalah 90°, yang merupakan sudut siku-siku.",hint:"Satu putaran penuh adalah 360° — berapakah seperempat dari itu?"},
{n:12,type:"tf",micro:"Sudut lebih besar tidak berarti garis yang digambar lebih besar",q:"Benar atau Salah: Kamu bisa menggambar dua sudut dengan garis sangat pendek dan dua sudut dengan garis sangat panjang, dan tetap membuat sudut bergaris-PENDEK lebih besar daripada yang bergaris-PANJANG, tergantung seberapa lebar setiap sudut terbuka.",answer:true,explain:"Ukuran sudut bergantung murni pada jumlah bukaan/putaran, bukan pada seberapa panjang garis yang membentuk sudut itu digambar.",hint:"Apakah menggambar garis sudut lebih panjang otomatis membuat sudut itu sendiri lebih besar?"},
{n:13,type:"mcq",micro:"Sudut konkret (buku terbuka)",q:"Sebuah buku yang terbaring benar-benar rata, terbuka di atas meja dengan kedua halamannya rata sejajar, membentuk sudut antara kedua sampulnya yang terlihat seperti apa?",options:["Sudut siku-siku (90°), karena sampulnya membentuk huruf L yang tegak","Sudut lurus (180°), karena sampulnya membentuk satu garis rata","Sudut tumpul (120°), karena sampulnya miring ke atas"],answer:1,explain:"Sebuah buku yang terbaring terbuka benar-benar rata membentuk sudut lurus (180°) antara kedua sampulnya.",hint:"Apakah buku yang terbaring benar-benar rata membentuk bentuk yang dekat dengan sudut persegi, atau dekat dengan satu garis rata lurus?"},
{n:14,type:"mcq",micro:"Soal cerita konkret (membandingkan bukaan pintu)",q:"Pintu A dibuka hanya sedikit celah. Pintu B dibuka hampir sepenuhnya, hampir rata dengan dinding. Pintu mana yang telah berputar melalui sudut yang lebih besar?",options:["Pintu B","Keduanya berputar melalui sudut yang sama","Pintu A"],answer:0,explain:"Pintu yang dibuka hampir sepenuhnya telah berputar melalui sudut yang jauh lebih besar daripada yang dibuka hanya sedikit celah.",hint:"Pintu mana yang berputar LEBIH BANYAK dari posisi awalnya yang tertutup?"},
{n:15,type:"mcq",micro:"Sudut konkret (kemiringan atap)",q:"Sebuah atap curam dan lancip memiliki sudut kecil dan tajam di puncaknya. Sebuah atap yang lebih datar dan kurang lancip memiliki sudut lebih lebar di puncaknya. Bentuk atap mana yang memiliki sudut puncak lebih besar?",options:["Kedua atap sama besar sudut puncaknya","Atap yang curam dan lancip","Atap yang lebih datar dan kurang lancip"],answer:2,explain:"Bentuk atap yang lebih datar memiliki sudut yang lebih lebar (lebih besar) di puncaknya daripada atap yang curam dan sangat lancip.",hint:"Apakah bentuk yang lebih datar dan kurang lancip mewakili sudut yang lebih lebar atau lebih sempit di puncaknya?"},
{n:16,type:"tf",micro:"Sebuah sudut membutuhkan titik puncak bersama",q:"Benar atau Salah: Sebuah sudut selalu dibentuk oleh dua garis (atau sinar) yang berbagi satu titik awal bersama, yang disebut titik puncak.",answer:true,explain:"Sebuah sudut didefinisikan oleh dua sinar yang bertemu di satu titik bersama yang disebut titik puncak.",hint:"Apakah kedua garis/sinar yang membentuk sudut perlu bertemu di satu titik awal bersama?"},
{n:17,type:"mcq",micro:"Sudut konkret (sudut tajam dunia nyata)",q:"Ujung yang sangat lancip dari sepotong pizza mewakili jenis sudut apa — kecil dan tajam, atau lebar dan terbuka?",options:["Lebar dan terbuka","Tidak keduanya — potongan pizza tidak memiliki sudut","Kecil dan tajam (sudut sempit)"],answer:2,explain:"Ujung lancip sepotong pizza adalah sudut kecil dan tajam (sempit).",hint:"Apakah ujung yang sangat lancip dari sepotong pizza terlihat seperti bukaan lebar, atau titik sempit dan tajam?"},
{n:18,type:"mcq",micro:"Soal cerita konkret (bilah kipas)",q:"Sebuah kipas tangan dibuka sebagian, membentuk sudut antara kedua tepi luarnya. Jika kamu membuka kipas itu lebih lebar, apa yang terjadi pada sudut ini?",options:["Sudutnya berkurang (mengecil)","Sudutnya bertambah (membesar)","Sudutnya tetap persis sama"],answer:1,explain:"Membuka kipas lebih lebar meningkatkan jumlah putaran antara kedua tepi luarnya, membuat sudutnya lebih besar.",hint:"Apakah membuka sesuatu lebih lebar menciptakan lebih banyak atau lebih sedikit 'putaran' antara kedua sisinya?"},
{n:19,type:"mcq",micro:"Sudut konkret (membandingkan dua tanjakan)",q:"Tanjakan A naik dengan sudut curam dan besar dari tanah. Tanjakan B naik dengan sudut landai dan kecil dari tanah. Tanjakan mana yang kemungkinan besar terasa lebih sulit didaki?",options:["Tanjakan A (tanjakan yang lebih curam, bersudut lebih besar)","Kedua tanjakan akan terasa persis sama sulitnya","Tanjakan B (tanjakan yang lebih landai, bersudut lebih kecil)"],answer:0,explain:"Tanjakan yang lebih curam (sudut lebih besar dari tanah) umumnya lebih sulit didaki daripada tanjakan yang lebih landai (sudut lebih kecil).",hint:"Apakah sudut yang lebih besar dari tanah umumnya menciptakan kemiringan yang lebih mudah atau lebih sulit didaki?"},
{n:20,type:"mcq",micro:"Memeriksa klaim sudut konkret",q:"Seseorang mengklaim bahwa sudut yang sangat KECIL dan digambar pendek (dengan garis pendek) otomatis lebih kecil daripada sudut yang sangat BESAR dan digambar panjang (dengan garis panjang). Apakah ini selalu benar?",options:["Ya — sudut dengan garis pendek memang otomatis lebih kecil karena bukaannya kurang terlihat dibanding sudut dengan garis panjang","Ya — panjang garis menentukan besar sudut, sehingga garis yang lebih panjang menghasilkan sudut yang lebih besar","Tidak — UKURAN sebenarnya (jumlah bukaan/putaran) suatu sudut tidak bergantung pada seberapa panjang garisnya digambar"],answer:2,explain:"Ukuran sebenarnya suatu sudut bergantung pada jumlah bukaan/putarannya, bukan pada seberapa panjang garisnya kebetulan digambar — sudut bergaris pendek tetap bisa lebih lebar daripada yang bergaris panjang.",hint:"Apakah PUTARAN/BUKAAN sebenarnya suatu sudut berubah hanya karena kamu menggambar garisnya lebih pendek atau lebih panjang?"},
{n:21,type:"mcq",micro:"Membaca busur derajat",q:"Sebuah busur derajat diletakkan pada sebuah sudut, dan sinar keduanya sejajar tepat dengan tanda 50°. Berapa ukuran sudut ini?",options:["50°","130°","500°"],answer:0,explain:"Membaca langsung di mana sinar kedua sejajar pada busur derajat memberikan ukuran sudutnya: 50°.",hint:"Angka pada busur derajat di mana sinar kedua menunjuk langsung memberimu ukuran sudutnya."},
{n:22,type:"mcq",micro:"Mengidentifikasi jenis sudut dari gambar (lancip)",q:"Sebuah gambar menunjukkan sudut berukuran 35°, jelas lebih kecil dari sudut siku-siku. Jenis sudut apa ini disebut?",options:["Sudut refleks","Sudut lancip","Sudut tumpul"],answer:1,explain:"Sudut mana pun yang lebih kecil dari 90° (seperti 35°) disebut sudut lancip.",hint:"Sudut yang berukuran KURANG dari 90° (sudut siku-siku) memiliki nama khusus — 'lancip' berarti 'tajam.'"},
{n:23,type:"mcq",micro:"Mengidentifikasi jenis sudut dari gambar (tumpul)",q:"Sebuah gambar menunjukkan sudut berukuran 120°, jelas lebih besar dari sudut siku-siku tetapi lebih kecil dari garis lurus. Jenis sudut apa ini disebut?",options:["Sudut tumpul","Sudut siku-siku","Sudut lancip"],answer:0,explain:"Sudut mana pun antara 90° dan 180° (seperti 120°) disebut sudut tumpul.",hint:"Sudut yang lebih besar dari 90° tetapi lebih kecil dari 180° (garis lurus) memiliki nama khusus — 'tumpul' berarti 'tidak tajam/lebar.'"},
{n:24,type:"mcq",micro:"Mengidentifikasi jenis sudut dari gambar (refleks)",q:"Sebuah gambar menunjukkan sudut berukuran 250°, lebih besar dari garis lurus (180°). Jenis sudut apa ini disebut?",options:["Sudut tumpul","Sudut refleks","Sudut siku-siku"],answer:1,explain:"Sudut mana pun yang lebih besar dari 180° (seperti 250°) disebut sudut refleks.",hint:"Sudut yang lebih besar dari garis lurus (180°) tetapi kurang dari putaran penuh (360°) memiliki nama khusus."},
{n:25,type:"order",micro:"Mengurutkan (jenis sudut dari terkecil ke terbesar)",q:"Urutkan jenis sudut berikut dari rentang khas terkecil ke rentang khas terbesar: sudut tumpul, sudut lancip, sudut refleks.",items:["sudut refleks","sudut lancip","sudut tumpul"],answer:[1,2,0],explain:"Diurutkan dari rentang terkecil ke terbesar: lancip (0°-90°), tumpul (90°-180°), refleks (180°-360°).",hint:"Bandingkan rentang derajat khas setiap jenis sudut — rentang mana yang dimulai paling kecil, dan mana yang meluas paling besar?"},
{n:26,type:"mcq",micro:"Membaca diagram (jumlah sudut pada garis lurus)",q:"Sebuah diagram menunjukkan garis lurus dengan satu sinar menjulur dari sebuah titik di atasnya, membagi 180° garis lurus itu menjadi dua sudut: satu berlabel 110°, yang lain tidak berlabel. Berapa sudut yang tidak berlabel itu?",options:["110°","180°","70°"],answer:2,explain:"Karena sudut-sudut pada garis lurus berjumlah 180°, sudut yang tidak berlabel=180−110=70°.",hint:"Sudut-sudut yang bersama membentuk garis lurus selalu berjumlah 180° — kurangkan sudut yang diketahui dari 180°."},
{n:27,type:"mcq",micro:"Membaca diagram (sudut mengelilingi titik)",q:"Sebuah diagram menunjukkan beberapa sudut bertemu di satu titik tunggal, bersama membentuk lingkaran penuh. Jika tiga sudutnya adalah 90°, 120°, dan 100°, dan ada satu sudut lagi yang tidak berlabel, berapa sudut yang tidak berlabel itu?",options:["360°","310°","50°"],answer:2,explain:"Sudut-sudut yang sepenuhnya mengelilingi satu titik berjumlah 360°; 90+120+100=310, jadi sudut yang tidak berlabel=360−310=50°.",hint:"Sudut-sudut yang bersama mengelilingi satu titik tunggal selalu berjumlah 360°."},
{n:28,type:"tf",micro:"Dua skala busur derajat",q:"Benar atau Salah: Sebagian besar busur derajat memiliki dua skala angka (satu terbaca kiri-ke-kanan, satu terbaca kanan-ke-kiri), jadi kamu perlu memeriksa skala mana yang benar dimulai dari 0° untuk sinar yang kamu ukur.",answer:true,explain:"Busur derajat biasanya memiliki dua skala yang berjalan berlawanan arah, dan menggunakan yang salah adalah kesalahan pengukuran yang umum.",hint:"Bisakah menggunakan skala yang salah dari dua skala angka busur derajat menyebabkan pembacaan sudut yang salah?"},
{n:29,type:"mcq",micro:"Membaca diagram (sudut dalam segitiga)",q:"Sebuah diagram segitiga menunjukkan dua dari tiga sudut dalamnya berlabel 50° dan 70°. Berapa sudut ketiganya?",options:["60°","180°","120°"],answer:0,explain:"Sudut-sudut dalam segitiga selalu berjumlah 180°; 50+70=120, jadi sudut ketiga=180−120=60°.",hint:"Ketiga sudut dalam segitiga apa pun selalu berjumlah tepat 180°."},
{n:30,type:"mcq",micro:"Membaca diagram (sudut dalam segi empat)",q:"Sebuah diagram bentuk empat sisi (segi empat) menunjukkan tiga dari empat sudut dalamnya berlabel 90°, 90°, dan 100°. Berapa sudut keempatnya?",options:["280°","80°","360°"],answer:1,explain:"Sudut-sudut dalam segi empat selalu berjumlah 360°; 90+90+100=280, jadi sudut keempat=360−280=80°.",hint:"Keempat sudut dalam segi empat apa pun selalu berjumlah tepat 360°."},
{n:31,type:"mcq",micro:"Membaca diagram (sudut bertolak belakang)",q:"Sebuah diagram menunjukkan dua garis lurus berpotongan, membentuk bentuk 'X.' Salah satu dari keempat sudut yang terbentuk berlabel 65°. Sudut yang tepat BERLAWANAN dengannya (menyeberangi X) tidak berlabel. Berapa sudut yang berlawanan itu?",options:["180°","115°","65°"],answer:2,explain:"Sudut yang tepat berlawanan satu sama lain saat dua garis berpotongan (disebut sudut bertolak belakang) selalu persis sama, jadi sudut yang berlawanan juga 65°.",hint:"Saat dua garis lurus berpotongan, kedua sudut yang tepat berlawanan satu sama lain (sudut bertolak belakang) selalu memiliki hubungan sama yang khusus."},
{n:32,type:"classify",micro:"Lancip, siku-siku, tumpul, atau refleks?",q:"Kelompokkan setiap ukuran sudut bergambar berdasarkan jenis sudutnya yang benar.",items:["30°","90°","150°","300°"],groups:["Lancip","Siku-siku","Tumpul","Refleks"],answer:{"Lancip":["30°"],"Siku-siku":["90°"],"Tumpul":["150°"],"Refleks":["300°"]},explain:"30° adalah lancip (di bawah 90°), 90° tepat siku-siku, 150° adalah tumpul (antara 90° dan 180°), dan 300° adalah refleks (di atas 180°).",hint:"Bandingkan setiap sudut dengan patokan kunci: 90° (siku-siku), 180° (lurus), dan 360° (putaran penuh)."},
{n:33,type:"mcq",micro:"Membaca diagram (sudut berpelurus)",q:"Sebuah diagram menunjukkan dua sudut yang bersama membentuk sudut siku-siku (90°) saat digabungkan, dengan satu berlabel 35°. Berapa sudut lainnya?",options:["65°","55°","90°"],answer:1,explain:"Sudut berpelurus berjumlah 90°; 90−35=55°.",hint:"Dua sudut yang bersama membentuk sudut siku-siku (disebut sudut berpelurus) berjumlah tepat 90°."},
{n:34,type:"mcq",micro:"Membaca diagram (sudut berpelurus lurus)",q:"Sebuah diagram menunjukkan dua sudut yang bersama membentuk garis lurus (180°) saat digabungkan, dengan satu berlabel 115°. Berapa sudut lainnya?",options:["65°","75°","180°"],answer:0,explain:"Sudut berpelurus lurus (bersuplemen) berjumlah 180°; 180−115=65°.",hint:"Dua sudut yang bersama membentuk garis lurus (disebut sudut bersuplemen) berjumlah tepat 180°."},
{n:35,type:"mcq",micro:"Membandingkan sudut bergambar (estimasi visual)",q:"Sudut A dalam sebuah gambar terlihat secara visual jauh lebih lebar terbuka daripada Sudut B. Tanpa mengukur secara tepat, apa yang bisa kamu perkirakan secara masuk akal?",options:["Sudut A kemungkinan besar memiliki ukuran derajat lebih besar daripada Sudut B","Sudut B kemungkinan besar berukuran lebih besar daripada Sudut A","Kedua sudut berukuran sama persis, karena gambar tidak bisa dipakai untuk membandingkan sudut"],answer:0,explain:"Sudut yang secara visual lebih lebar terbuka umumnya sesuai dengan ukuran derajat yang lebih besar, bahkan sebelum pengukuran yang tepat.",hint:"Apakah sudut yang secara visual terlihat lebih lebar umumnya sesuai dengan ukuran derajat yang lebih besar atau lebih kecil?"},
{n:36,type:"tf",micro:"Estimasi piktorial dengan jenis sudut",q:"Benar atau Salah: Sebuah sudut yang terlihat hanya sedikit lebih terbuka daripada sudut siku-siku (bentuk sudut buku) kemungkinan besar adalah sudut tumpul, bukan sudut refleks.",answer:true,explain:"Sudut yang hanya sedikit lebih lebar dari sudut siku-siku (90°) jatuh dalam rentang tumpul (90°-180°), jauh dari rentang refleks (di atas 180°).",hint:"Apakah sudut yang hanya sedikit lebih besar dari sudut siku-siku lebih dekat ke rentang tumpul, atau rentang refleks yang jauh lebih besar?"},
{n:37,type:"mcq",micro:"Membaca diagram (sudut dalam bentuk nyata, segitiga sama kaki)",q:"Sebuah diagram segitiga menunjukkan dua sudut alas sama, masing-masing berlabel 65°. Berapa sudut ketiga (atas)?",options:["130°","65°","50°"],answer:2,explain:"180−65−65=50°, menggunakan aturan jumlah sudut segitiga.",hint:"Jumlahkan kedua sudut yang diketahui bersama, lalu kurangkan dari total jumlah sudut segitiga 180°."},
{n:38,type:"mcq",micro:"Menjembatani piktorial ke abstrak (pola jumlah sudut)",q:"Melihat beberapa diagram segitiga dengan kombinasi sudut berbeda (50+60+70=180, 90+45+45=180, 30+30+120=180), pola apa yang kamu perhatikan?",options:["Ketiga sudut dalam setiap segitiga berjumlah antara 90° dan 270° tergantung bentuk segitiganya, dan tidak selalu sama","Ketiga sudut dalam setiap segitiga selalu berjumlah tepat 180°, tidak peduli bentuk segitiganya","Hanya segitiga dengan sudut siku-siku yang jumlah sudutnya 180°"],answer:1,explain:"Tidak peduli bentuk segitiganya, ketiga sudut dalamnya selalu berjumlah tepat 180° — aturan geometris yang konsisten.",hint:"Apakah ketiga contoh segitiga, meskipun terlihat berbeda, berbagi jumlah sudut total yang sama?"},
{n:39,type:"mcq",micro:"Soal cerita piktorial (sudut dalam segitiga siku-siku)",q:"Sebuah diagram segitiga siku-siku menunjukkan satu sudut sudah ditandai sebagai sudut siku-siku (90°), dan sudut kedua berlabel 35°. Berapa sudut ketiganya?",options:["55°","65°","125°"],answer:0,explain:"180−90−35=55°, menggunakan aturan jumlah sudut segitiga.",hint:"Kurangkan baik sudut siku-siku yang diketahui (90°) maupun sudut lain yang diketahui dari total 180°."},
{n:40,type:"mcq",micro:"Memilih strategi gambar untuk menemukan sudut yang hilang",q:"Untuk menemukan sudut yang hilang dalam diagram dua garis berpotongan dengan tiga sudut sudah berlabel, apa pendekatan yang membantu?",options:["Ukur sudut yang hilang dengan gambar kasar saja, karena hubungan antar sudut tidak bisa dipakai untuk menghitung sudut yang tidak diketahui","Gunakan hubungan sudut (sudut bertolak belakang sama; sudut pada garis lurus berjumlah 180°) untuk menghitung sudut yang hilang langkah demi langkah","Jumlahkan semua sudut yang diketahui lalu anggap hasilnya adalah sudut yang hilang, tanpa memakai hubungan garis lurus atau sudut bertolak belakang"],answer:1,explain:"Menerapkan aturan hubungan sudut yang diketahui (sudut bertolak belakang sama, sudut garis lurus berjumlah 180°) membiarkanmu menghitung sudut yang hilang secara tepat, tanpa perlu mengukurnya secara fisik.",hint:"Bisakah hubungan antara sudut pada garis lurus, atau sudut bertolak belakang, membantumu menghitung sudut yang hilang tanpa busur derajat?"},
{n:41,type:"mcq",micro:"Jenis sudut dari ukuran derajat",q:"Sebuah sudut berukuran 42°. Jenis sudut apa ini?",options:["Siku-siku","Tumpul","Lancip"],answer:2,explain:"Sudut mana pun yang kurang dari 90° (seperti 42°) adalah sudut lancip.",hint:"Apakah 42° kurang dari, sama dengan, atau lebih besar dari 90°?"},
{n:42,type:"mcq",micro:"Jenis sudut dari ukuran derajat (tumpul)",q:"Sebuah sudut berukuran 168°. Jenis sudut apa ini?",options:["Siku-siku","Tumpul","Lancip"],answer:1,explain:"Sudut mana pun antara 90° dan 180° (seperti 168°) adalah sudut tumpul.",hint:"Apakah 168° berada antara 90° dan 180°?"},
{n:43,type:"mcq",micro:"Perhitungan sudut berpelurus",q:"Dua sudut berpelurus. Satu berukuran 27°. Berapa sudut lainnya?",options:["63°","153°","27°"],answer:0,explain:"Sudut berpelurus berjumlah 90°; 90−27=63°.",hint:"Sudut berpelurus selalu berjumlah tepat 90° — kurangkan sudut yang diketahui dari 90°."},
{n:44,type:"mcq",micro:"Perhitungan sudut bersuplemen",q:"Dua sudut bersuplemen. Satu berukuran 78°. Berapa sudut lainnya?",options:["12°","282°","102°"],answer:2,explain:"Sudut bersuplemen berjumlah 180°; 180−78=102°.",hint:"Sudut bersuplemen selalu berjumlah tepat 180° — kurangkan sudut yang diketahui dari 180°."},
{n:45,type:"mcq",micro:"Perhitungan jumlah sudut segitiga",q:"Sebuah segitiga memiliki sudut berukuran 48° dan 62°. Berapa sudut ketiganya?",options:["110°","180°","70°"],answer:2,explain:"180−48−62=70°.",hint:"Kurangkan kedua sudut yang diketahui dari total jumlah sudut segitiga, 180°."},
{n:46,type:"mcq",micro:"Perhitungan jumlah sudut segi empat",q:"Sebuah segi empat memiliki tiga sudut berukuran 85°, 95°, dan 100°. Berapa sudut keempatnya?",options:["80°","280°","90°"],answer:0,explain:"360−85−95−100=80°.",hint:"Kurangkan ketiga sudut yang diketahui dari total jumlah sudut segi empat, 360°."},
{n:47,type:"order",micro:"Mengurutkan (menemukan sudut yang hilang pada garis lurus)",q:"Urutkan langkah-langkah berikut untuk menemukan sudut yang hilang saat dua sudut bersama membentuk garis lurus, dan satu sudut diberikan sebagai 130°.",items:["Kurangkan 130° dari 180°, memberikan 50° sebagai sudut yang hilang","Sadari bahwa sudut pada garis lurus berjumlah 180°","Identifikasi sudut yang diketahui (130°) yang diberikan dalam diagram"],answer:[2,1,0],explain:"Pertama identifikasi sudut yang diketahui, lalu ingat aturan sudut garis lurus (berjumlah 180°), lalu kurangkan untuk menemukan sudut yang hilang.",hint:"Bisakah kamu mengurangkan dari 180° sebelum kamu ingat bahwa sudut garis lurus berjumlah 180° sejak awal?"},
{n:48,type:"mcq",micro:"Perhitungan sudut bertolak belakang",q:"Dua garis lurus berpotongan, membentuk empat sudut. Satu sudut berukuran 73°. Berapa sudut yang tepat berlawanan dengannya (sudut bertolak belakang)?",options:["180°","73°","107°"],answer:1,explain:"Sudut bertolak belakang (tepat berlawanan satu sama lain saat dua garis berpotongan) selalu persis sama, jadi sudut yang berlawanan juga 73°.",hint:"Sudut bertolak belakang (tepat menyeberang satu sama lain di titik perpotongan) selalu memiliki hubungan sama yang khusus."},
{n:49,type:"mcq",micro:"Perhitungan sudut mengelilingi titik",q:"Empat sudut bertemu di satu titik tunggal, bersama membentuk lingkaran penuh. Tiga di antaranya berukuran 80°, 95°, dan 110°. Berapa sudut keempatnya?",options:["360°","75°","285°"],answer:1,explain:"360−80−95−110=75°.",hint:"Kurangkan ketiga sudut yang diketahui dari total jumlah sudut-mengelilingi-titik, 360°."},
{n:50,type:"classify",micro:"Berpelurus, bersuplemen, atau bukan keduanya?",q:"Kelompokkan setiap pasangan sudut berdasarkan apakah kedua sudut itu berpelurus (berjumlah 90°), bersuplemen (berjumlah 180°), atau bukan keduanya.",items:["70° dan 20°","110° dan 70°","60° dan 60°","25° dan 65°"],groups:["Berpelurus","Bersuplemen","Bukan Keduanya"],answer:{"Berpelurus":["70° dan 20°","25° dan 65°"],"Bersuplemen":["110° dan 70°"],"Bukan Keduanya":["60° dan 60°"]},explain:"70+20=90 dan 25+65=90 (keduanya berpelurus); 110+70=180 (bersuplemen); 60+60=120, yang tidak cocok dengan total mana pun.",hint:"Jumlahkan setiap pasangan sudut bersama dan bandingkan jumlahnya dengan 90° dan 180°."},
{n:51,type:"mcq",micro:"Soal sudut dunia nyata (menemukan sudut yang hilang pada rangka atap)",q:"Sebuah rangka atap segitiga memiliki sudut siku-siku di sudut alasnya dan sudut 35° di sudut lainnya. Berapa sudut ketiga (di puncak)?",options:["125°","145°","55°"],answer:2,explain:"180−90−35=55°.",hint:"Kurangkan sudut siku-siku (90°) dan sudut lain yang diketahui dari total jumlah sudut segitiga, 180°."},
{n:52,type:"mcq",micro:"Soal sudut dunia nyata (sudut bukaan laptop)",q:"Engsel sebuah laptop memungkinkannya terbuka sampai sudut lurus maksimum 180°. Jika tutupnya saat ini terbuka sampai 125°, berapa lagi yang bisa terbuka sebelum mencapai maksimum?",options:["55°","305°","125°"],answer:0,explain:"180−125=55° lagi yang bisa terbuka.",hint:"Kurangkan sudut saat ini dari sudut maksimum yang mungkin (180°)."},
{n:53,type:"mcq",micro:"Soal cerita (sudut pada garis, tiga sudut)",q:"Tiga sudut berada di sepanjang garis lurus, berukuran 40°, 65°, dan sudut ketiga yang tidak diketahui. Berapa sudut ketiganya?",options:["105°","75°","180°"],answer:1,explain:"180−40−65=75°.",hint:"Kurangkan kedua sudut yang diketahui dari total jumlah garis lurus, 180°."},
{n:54,type:"mcq",micro:"Soal cerita (segi empat dengan dua sudut siku-siku)",q:"Sebuah segi empat memiliki dua sudut siku-siku (90° masing-masing) dan sudut ketiga 60°. Berapa sudut keempatnya?",options:["120°","150°","240°"],answer:0,explain:"360−90−90−60=120°.",hint:"Kurangkan ketiga sudut yang diketahui dari total jumlah sudut segi empat, 360°."},
{n:55,type:"mcq",micro:"Membandingkan hasil berbasis sudut",q:"Mana yang lebih besar: sudut yang hilang dalam garis lurus dengan sudut yang diketahui 100°, atau sudut yang hilang dalam pasangan sudut siku-siku dengan sudut yang diketahui 40°?",options:["Keduanya sama","Sudut yang hilang pada pasangan sudut siku-siku (50°)","Sudut yang hilang pada garis lurus (80°)"],answer:2,explain:"Garis lurus: 180−100=80°. Pasangan berpelurus: 90−40=50°. 80° lebih besar dari 50°.",hint:"Hitung kedua sudut yang hilang secara tepat, lalu bandingkan secara langsung."},
{n:56,type:"tf",micro:"Memeriksa perhitungan sudut dengan estimasi",q:"Benar atau Salah: Jika kamu menghitung sudut ketiga segitiga (dengan dua sudut yang diketahui 60° dan 70°) dan mendapat 200°, kemungkinan ada yang salah.",answer:true,explain:"Ketiga sudut segitiga harus berjumlah tepat 180°, jadi sudut ketiga 200° (yang akan membuat total 330°) tidak mungkin — sudut ketiga yang benar adalah 50°.",hint:"Bisakah ketiga sudut dalam segitiga pernah berjumlah lebih dari 180°?"},
{n:57,type:"mcq",micro:"Soal cerita (sudut bertolak belakang, perpotongan nyata)",q:"Dua jalan lurus berpotongan di sebuah persimpangan, membentuk empat sudut. Satu sudut (antara kedua jalan itu) berukuran 55°. Berapa sudut yang bertolak belakang dengannya?",options:["55°","180°","125°"],answer:0,explain:"Sudut bertolak belakang selalu sama, jadi sudut yang berlawanan juga 55°.",hint:"Sudut bertolak belakang (tepat berlawanan) di titik perpotongan selalu berbagi ukuran yang persis sama."},
{n:58,type:"mcq",micro:"Hubungan fakta (sudut pada garis vs putaran penuh)",q:"Karena sudut pada garis lurus berjumlah 180°, dan sudut yang sepenuhnya mengelilingi titik berjumlah 360°, apa hubungan antara kedua total ini?",options:["360° tepat tiga kali 180°, karena putaran penuh tiga setengah-garis","360° tepat dua kali 180°, karena putaran penuh tepat dua kali setengah-garis-lurus","360° tidak berhubungan dengan 180°, karena kedua jenis sudut diukur dengan cara berbeda"],answer:1,explain:"Putaran penuh 360° tepat dua kali setengah-putaran garis lurus 180°.",hint:"Apakah nilai satu lingkaran penuh (360°) berhubungan dengan setengah putaran (180°) melalui hubungan penggandaan sederhana?"},
{n:59,type:"mcq",micro:"Membandingkan jumlah sudut",q:"Mana yang lebih besar: jumlah ketiga sudut dalam segitiga, atau jumlah keempat sudut dalam segi empat?",options:["Jumlah sudut segitiga (180°)","Keduanya persis sama","Jumlah sudut segi empat (360°)"],answer:2,explain:"Jumlah sudut segi empat (360°) lebih besar dari jumlah sudut segitiga (180°).",hint:"Bandingkan langsung kedua total jumlah-sudut yang diketahui: 180° untuk segitiga, 360° untuk segi empat."},
{n:60,type:"mcq",micro:"Memilih hubungan yang tepat",q:"Sebuah soal mengatakan: 'Dua sudut berdampingan di sepanjang garis lurus. Satu 3 kali lebih besar dari yang lain. Temukan kedua sudut.' Hubungan apa yang harus kamu gunakan dulu?",options:["Sadari kedua sudut harus berjumlah 360° (putaran penuh), lalu gunakan total itu dengan petunjuk 'satu 3 kali yang lain' untuk menyelesaikan keduanya","Sadari kedua sudut harus berjumlah 180° (garis lurus), lalu gunakan total itu dengan petunjuk 'satu 3 kali yang lain' untuk menyelesaikan keduanya","Kalikan 180° dengan 3 untuk mendapat sudut besar, lalu anggap sudut kecil sebesar 3° karena perbandingan 3 kali dihitung begitu"],answer:1,explain:"Menyusun jumlah garis lurus (180°) bersama hubungan 'satu 3 kali yang lain' (sudut kecil=x, sudut besar=3x, jadi x+3x=180, memberikan x=45° dan 3x=135°) adalah pendekatan yang benar.",hint:"Apakah mengetahui kedua sudut membentuk garis lurus memberimu total kunci untuk dikerjakan, sebelum menggunakan detail 'satu 3 kali yang lain'?"},
{n:61,type:"mcq",micro:"Mengapa hubungan sudut penting untuk konstruksi nyata",q:"Mengapa sangat penting bagi tukang kayu yang membangun rangka atap segitiga untuk menghitung dengan benar ketiga sudutnya menggunakan aturan segitiga 180°, alih-alih hanya memperkirakan dengan mata?",options:["Karena bahkan kesalahan hitung sudut kecil bisa menyebabkan potongan rangka tidak pas bersama dengan benar atau tidak stabil secara struktural setelah dirakit","Karena sudut atap tidak memengaruhi kekuatan rangka, sehingga tukang kayu boleh memotong kayu dengan sudut perkiraan saja tanpa perhitungan teliti","Karena tukang kayu menggunakan sudut yang sama untuk semua atap, sehingga perhitungan sudut hanya perlu dilakukan satu kali seumur hidup"],answer:0,explain:"Perhitungan sudut yang presisi (menggunakan aturan segitiga 180° yang andal) menjamin bagian struktural pas bersama secara benar dan aman — menaksir dengan mata berisiko kesesuaian yang buruk atau tidak stabil.",hint:"Bisakah kesalahan sudut kecil yang ditaksir dengan mata dalam rangka atap menyebabkan masalah kesesuaian atau stabilitas struktural nyata?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa menemukan sudut yang hilang pada garis lurus (dengan satu sudut yang diketahui 115°) dengan menulis 115+180=295° sebagai jawabannya. Temukan kesalahannya dan jelaskan metode yang benar.",explain:"Membingungkan 'jumlahkan sudut ke 180°' dengan 'kurangkan sudut dari 180°' adalah salah satu kesalahan sudut-garis-lurus yang paling umum.",hint:"Haruskah menemukan sudut garis lurus yang hilang melibatkan menjumlahkan sudut yang diketahui ke 180°, atau menguranginya dari 180°?",sample:"Siswa itu menjumlahkan sudut yang diketahui ke 180° alih-alih menguranginya — metode yang benar adalah MENGURANGKAN sudut yang diketahui DARI 180° (karena sudut pada garis lurus berjumlah 180°, bukan menjumlahkan sampai termasuk 180° lagi): 180−115=65°."},
{n:63,type:"open",micro:"Estimasi vs penalaran tepat",q:"Kapan perkiraan sudut visual cepat (seperti menaksir apakah sesuatu terlihat 'kira-kira sudut siku-siku') sudah cukup baik, dan kapan kamu membutuhkan pengukuran busur derajat yang tepat? Berikan satu contoh nyata masing-masing.",explain:"Mengenali kapan presisi sudut benar-benar penting versus kapan perkiraan visual yang masuk akal sudah cukup mencerminkan penalaran pengukuran yang matang.",hint:"Pikirkan situasi di mana perkiraan sudut kasar tidak terlalu masalah, dibandingkan dengan situasi di mana itu benar-benar masalah.",sample:"Perkiraan visual cepat sudah cukup untuk hal seperti kira-kira memeriksa apakah bingkai foto terlihat cukup rata di dinding; pengukuran busur derajat (atau alat presisi) yang tepat penting untuk hal seperti memotong potongan bersudut untuk perakitan furnitur, di mana bahkan kesalahan sudut kecil bisa berarti potongannya tidak pas bersama dengan benar."},
{n:64,type:"mcq",micro:"Penalaran tentang klaim sudut yang menyesatkan",q:"Sebuah iklan furnitur mengklaim sebuah kursi memiliki 'sudut sandaran ergonomis sempurna 110°,' tetapi tidak menyebutkan bahwa kenyamanan ergonomis juga sangat bergantung pada tinggi kursi, bantalan, dan ukuran tubuh orang itu sendiri. Mengapa fokus HANYA pada angka sudut mungkin menyesatkan?",options:["Karena sudut 110° adalah sudut paling nyaman bagi orang dewasa, sehingga satu angka itu sudah cukup menjamin kursi nyaman bagi pemakainya","Karena iklan tidak boleh menyebut sudut sandaran, dan klaim ergonomis harus berupa pernyataan perasaan tanpa angka","Karena satu pengukuran sudut saja tidak menangkap setiap faktor yang sebenarnya menentukan kenyamanan atau kesesuaian ergonomis dunia nyata"],answer:2,explain:"Satu angka sudut, meskipun pengukuran yang nyata dan relevan, tidak menangkap setiap faktor lain (tinggi kursi, bantalan, perbedaan tubuh individual) yang bersama menentukan kenyamanan ergonomis yang genuine.",hint:"Apakah mengetahui HANYA ukuran sudut sandaran menjamin itu akan nyaman untuk setiap orang, terlepas dari faktor lain?"},
{n:65,type:"open",micro:"Penalaran dunia nyata",q:"Mengapa pemasang panel surya perlu dengan hati-hati menghitung SUDUT kemiringan yang benar untuk panel surya berdasarkan garis lintang lokasi, alih-alih hanya memasangnya pada sudut yang terlihat nyaman secara acak?",explain:"Ini mencerminkan penerapan penalaran sudut dunia nyata yang genuine, menghubungkan perhitungan sudut dengan hasil efisiensi energi yang sebenarnya.",hint:"Bisakah memasang panel surya pada sudut yang dihitung dengan buruk secara bermakna mengurangi berapa banyak sinar matahari (dan energi) yang sebenarnya ditangkapnya?",sample:"Sudut di mana sinar matahari mengenai panel surya secara langsung mempengaruhi berapa banyak energi yang bisa ditangkapnya — panel yang dipasang pada sudut yang tidak cocok secara wajar dengan garis lintang lokasi dan posisi matahari khas umumnya akan menangkap sinar matahari yang bisa digunakan jauh lebih sedikit sepanjang tahun, menunjukkan bahwa perhitungan sudut yang hati-hati memiliki dampak praktis yang nyata dan bisa diukur pada efisiensi energi surya."},
{n:66,type:"mcq",micro:"Memilih strategi yang efisien",q:"Untuk menemukan sudut yang hilang dalam diagram dua garis lurus berpotongan (di mana sudut bertolak belakang terlihat ditandai sama), strategi mana yang paling cepat?",options:["Mengukur setiap sudut tunggal dengan busur derajat fisik, bahkan ketika hubungan geometris yang diketahui bisa memberikan jawaban seketika tanpa berpikir lagi","Kenali hubungan sudut bertolak belakang segera (sudut yang hilang sama dengan sudut berlabel yang tepat berlawanan dengannya), alih-alih mencoba menurunkannya lagi dari awal","Tidak ada cara yang lebih cepat daripada menebak sudut yang hilang"],answer:1,explain:"Mengenali hubungan yang diketahui (seperti sudut bertolak belakang yang sama) membiarkanmu menemukan sudut yang hilang seketika, tanpa perlu mengukur ulang atau menurunkannya lagi.",hint:"Jika sudut bertolak belakang selalu sama menurut definisinya, apakah kamu perlu mengukur ulang yang hilang, atau bisa menggunakan hubungan itu langsung?"},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua orang menghitung sudut ketiga sebuah segitiga (dengan dua sudut yang diketahui 55° dan 65°) dan mendapat 60° dan 120°. Jelaskan rencana langkah demi langkah untuk menemukan jawaban yang benar.",explain:"Memverifikasi bahwa ketiga sudut benar-benar berjumlah tepat 180° adalah cara andal menangkap dan memperbaiki kesalahan perhitungan sudut segitiga.",hint:"Akankah memeriksa apakah setiap jawaban yang diusulkan, ditambahkan ke kedua sudut yang diketahui, benar-benar berjumlah tepat 180° membantumu mengidentifikasi yang benar?",sample:"Hitung ulang dengan hati-hati: 180−55−65=60° — memeriksa ini mengonfirmasi 60° benar (dan ketiga sudut 55+65+60=180, dengan benar berjumlah 180°), sementara jawaban lainnya (120°) akan membuat total 55+65+120=240°, yang tidak mungkin untuk segitiga, mengungkapkan jawaban itu salah."},
{n:68,type:"mcq",micro:"Ketika mental math mungkin gagal",q:"Untuk menemukan sudut yang hilang dalam diagram kompleks dengan 5 atau 6 sudut berbeda dan beberapa hubungan (bertolak belakang, garis lurus, jumlah segitiga) digabungkan, mengapa metode tertulis langkah-demi-langkah mungkin lebih aman daripada mental math murni?",options:["Karena melacak beberapa hubungan sudut berbeda dan perhitungan parsial murni di kepala membuatnya mudah kehilangan jejak satu langkah atau menerapkan hubungan yang salah ke pasangan sudut yang salah","Karena melacak banyak sudut dan hubungan sekaligus lebih akurat dilakukan di kepala, sedangkan menulis langkah menambah kemungkinan salah salin pada setiap baris perhitungan yang dibuat siswa","Karena sudut-sudut dalam diagram kompleks tidak boleh dituliskan, dan hanya boleh dihitung dengan busur derajat tanpa mencatat hasil sementara di kertas"],answer:0,explain:"Diagram sudut kompleks dengan banyak hubungan sangat rentan kesalahan pelacakan mental, membuat pendekatan tertulis langkah-demi-langkah lebih aman.",hint:"Apakah melacak 5-6 hubungan sudut berbeda semudah dilakukan murni di kepala seperti satu pasangan sudut sederhana tunggal?"},
{n:69,type:"open",micro:"Menerapkan penalaran sudut pada keadilan",q:"Tiga saudara ingin membagi pizza bundar menjadi tiga potongan berukuran tidak sama berdasarkan seberapa lapar setiap orang merasa (bukan sepertiga yang sama persis). Jelaskan bagaimana memahami bahwa sudut mengelilingi titik berjumlah 360° membantu mereka membaginya secara adil sesuai proporsi yang mereka sepakati sendiri.",explain:"Menghubungkan aturan sudut-mengelilingi-titik langsung dengan diskusi keadilan nyata tentang membagi sumber daya bundar bersama secara tidak sama tetapi disengaja.",hint:"Akankah mengetahui bahwa semua sudut potongan harus berjumlah tepat 360° membantu para saudara membagi seluruh pizza tanpa sisa atau tumpang tindih yang tidak adil, bahkan jika potongannya tidak sama?",sample:"Karena sudut semua potongan mengelilingi pusat pizza itu harus berjumlah tepat 360°, para saudara itu bisa sepakat pada proporsi yang adil (seperti satu saudara mendapat sedikit lebih dari sepertiga jika mereka lebih lapar) dan lalu menghitung bagian sudut tepat setiap orang berdasarkan proporsi yang disepakati itu (misalnya, saudara yang lebih lapar mendapat 150°, dan kedua lainnya membagi sisa 210° di antara mereka) — menggunakan total 360° menjamin seluruh pizza diperhitungkan dengan tepat, tanpa sisa atau tumpang tindih."},
{n:70,type:"mcq",micro:"Penalaran tentang aturan hubungan sudut",q:"Mengapa sudut pada garis lurus selalu berjumlah 180°, tidak peduli berapa banyak sudut yang membagi garis itu?",options:["Karena garis lurus bukan sudut apa pun, sehingga jumlah sudut yang membaginya berubah-ubah tergantung banyaknya sudut yang dibuat pada garis itu","Karena jumlah 180° hanya berlaku bila garis dibagi menjadi dua sudut, sedangkan bila dibagi menjadi tiga sudut atau lebih jumlahnya menjadi berbeda","Karena garis lurus itu sendiri ADALAH sudut 180°, jadi sudut apa pun yang lebih kecil yang membaginya harus selalu berjumlah kembali ke total 180° yang sama itu"],answer:2,explain:"Garis lurus itu sendiri adalah sudut 180°, jadi berapa pun banyak sudut lebih kecil yang membaginya menjadi bagian-bagian, bagian-bagian itu harus selalu berjumlah kembali ke total 180° aslinya.",hint:"Jika garis lurus itu sendiri mewakili sudut 180°, haruskah sudut apa pun yang membaginya selalu berjumlah kembali ke total 180° yang sama itu, tidak peduli berapa banyak bagiannya?"},
{n:71,type:"open",micro:"Penalaran estimasi kehidupan nyata",q:"Sebelum menggunakan busur derajat untuk pengukuran yang tepat, bagaimana cepat membandingkan sudut dengan sudut siku-siku yang diketahui (seperti sudut selembar kertas) bisa membantumu merasakan apakah pengukuranmu nanti terlihat masuk akal?",explain:"Ini adalah penggunaan praktis nyata dari referensi fisik sederhana (sudut siku-siku) untuk pemeriksaan kewajaran cepat pada pengukuran sudut.",hint:"Akankah membandingkan sudut yang tidak diketahui dengan referensi 90° yang diketahui (seperti sudut kertas) membantumu menangkap pengukuran nanti yang jelas salah?",sample:"Memegang referensi sudut siku-siku (seperti sudut selembar kertas) di sebelah sudut yang tidak diketahui membiarkanmu cepat menilai apakah itu terlihat lebih besar atau lebih kecil dari 90° — jika pengukuran busur derajatmu nanti ternyata, katakanlah, 170° untuk sudut yang secara visual terlihat jelas LEBIH KECIL dari sudut siku-siku, ketidakcocokan itu akan menjadi sinyal langsung bahwa ada yang salah dengan pengukurannya."},
{n:72,type:"mcq",micro:"Mengenali pola dalam urutan sudut",q:"Sebuah urutan poligon beraturan memiliki jumlah sudut dalam 180° (segitiga, 3 sisi), 360° (segi empat, 4 sisi), 540° (segi lima, 5 sisi). Pola apa yang kamu perhatikan saat jumlah sisi bertambah?",options:["Jumlah sudut tetap persis sama tidak peduli berapa banyak sisi yang ditambahkan","Setiap sisi tambahan menambahkan 180° lagi ke total jumlah sudut dalam","Jumlah sudut menurun saat lebih banyak sisi ditambahkan"],answer:1,explain:"Setiap sisi tambahan menambahkan 180° lagi ke total jumlah sudut dalam bentuk itu (pola yang berhubungan dengan bagaimana bentuk itu bisa dibagi menjadi lebih banyak segitiga).",hint:"Lihat celah antara setiap total dalam urutan itu — 180°, 360°, 540° — berapa kenaikan yang konsisten?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Jelaskan perhitungan terkait-sudut nyata di mana kamu akan menggunakan perkiraan visual/mental cepat, dan satu di mana kamu ingin menghitung dengan hati-hati dan presisi penuh (atau busur derajat sungguhan).",explain:"Mengenali bahwa strategi jalan pintas/visual bekerja paling baik untuk situasi santai dan bertoleransi, sementara konteks kritis-presisi mendapat manfaat dari pengukuran yang hati-hati dan tepat, menunjukkan penilaian strategis yang nyata.",hint:"Apakah perkiraan sudut visual cepat bekerja sama baiknya di setiap situasi, atau hanya ketika kesalahan kecil tidak menyebabkan masalah nyata yang terlihat?",sample:"Untuk hal seperti kira-kira memeriksa apakah rak terlihat rata atau bingkai foto terlihat lurus, perkiraan visual cepat sudah cukup; tetapi untuk hal seperti menghitung sudut tepat yang dibutuhkan untuk memotong potongan kayu bingkai foto yang harus pas bersama sempurna, pengukuran yang hati-hati dan presisi jauh lebih penting, karena bahkan kesalahan sudut kecil bisa meninggalkan celah yang terlihat di mana potongannya bertemu."},
{n:74,type:"mcq",micro:"Menafsirkan sudut perkiraan",q:"Sebuah laporan mengatakan sebuah lereng bukit miring 'kira-kira 25°.' Apa yang disarankan 'kira-kira' tentang sudut tepatnya?",options:["Sudut sebenarnya persis 25° di setiap titik lereng karena kata 'kira-kira' hanya hiasan dan tidak mengubah angka yang disebutkan laporan","Sudut sebenarnya jauh lebih besar dari 25° karena laporan biasanya menyebut sudut yang lebih kecil agar lereng terlihat aman bagi pendaki","Sudut sebenarnya kemungkinan dekat dengan 25° tetapi mungkin bukan nilai yang tepat itu secara sempurna di mana-mana di lereng bukit itu"],answer:2,explain:"'Kira-kira' menandakan perkiraan — sudut sebenarnya diharapkan dekat dengan, tetapi belum tentu sempurna dan tepat (atau sepenuhnya konsisten di seluruh lereng bukit), 25°.",hint:"Apakah 'kira-kira 25°' menjanjikan presisi sempurna dan konsistensi di mana-mana di lereng bukit itu, atau hanya kedekatan keseluruhan yang masuk akal?"},
{n:75,type:"open",micro:"Perhitungan sudut di bawah tekanan",q:"Saat kompetisi geometri yang cepat di mana siswa harus cepat menemukan sudut yang hilang dalam diagram, kebiasaan apa yang membantu menghindari kesalahan ceroboh bahkan saat terburu-buru?",explain:"Kebiasaan spesifik dan cepat 'hubungan mana yang berlaku di sini?' membantu menjaga akurasi bahkan saat bekerja dengan cepat di bawah tekanan.",hint:"Akankah cepat mengonfirmasi hubungan sudut MANA yang berlaku (180° vs 360° vs bertolak-belakang-sama) sebelum menghitung membantu menghindari kekacauan yang terburu-buru?",sample:"Cepat mengidentifikasi hubungan sudut MANA yang berlaku (garis lurus=180°, titik penuh=360°, segitiga=180°, sudut bertolak belakang=sama) sebelum memulai perhitungan apa pun membantu menghindari kesalahan terburu-buru umum yaitu menerapkan total yang salah (seperti menggunakan 180° padahal diagramnya sebenarnya membutuhkan 360°), bahkan saat bekerja di bawah tekanan waktu."},
{n:76,type:"mcq",micro:"Koneksi jenis sudut dan desain dunia nyata",q:"Mengapa perancang furnitur dan arsitektur mungkin dengan sengaja memilih sudut tumpul (bukan hanya sudut siku-siku) untuk beberapa sandaran kursi atau desain dinding?",options:["Karena sudut tumpul yang lebih lebar kadang bisa memberikan sandaran yang lebih nyaman atau tampilan visual yang lebih lembut dan kurang kotak daripada sudut siku-siku 90° yang tegas","Karena sudut tumpul lebih kuat secara struktural daripada sudut siku-siku, sehingga furnitur dan bangunan lebih baik memakainya untuk setiap bagian","Karena sudut siku-siku tidak boleh dipakai dalam desain furnitur dan arsitektur, sehingga semua sudut harus tumpul demi keselamatan pengguna bangunan itu"],answer:0,explain:"Perancang kadang dengan sengaja memilih sudut tumpul untuk kenyamanan praktis (seperti sandaran bersandar) atau kelembutan estetika, bukan hanya default ke sudut siku-siku.",hint:"Bisakah sudut yang lebih lebar (tumpul) kadang menciptakan efek yang lebih nyaman atau visual yang berbeda daripada sudut siku-siku yang tegas?"},
{n:77,type:"open",micro:"Menjelaskan jenis sudut ke orang lain",q:"Seorang siswa yang lebih muda membingungkan sudut 'lancip' dan 'tumpul,' lupa yang mana yang 'kecil, tajam.' Apa yang akan kamu ajarkan padanya, dan mengapa itu membantu?",explain:"Mengajarkan strategi asosiasi kata yang mudah diingat dan konkret mencerminkan pemahaman nyata tentang apa yang membuat istilah kosakata abstrak melekat bagi pembelajar.",hint:"Bisakah menghubungkan BUNYI atau KESAN kata 'lancip' dan 'tumpul' dengan makna sebenarnya (kecil/tajam vs lebar/tidak tajam) membantu membuat perbedaannya lebih mudah diingat?",sample:"Saya akan menghubungkan 'lancip' dengan kata sehari-hari yang mirip bunyinya — sesuatu yang kecil dan tajam seperti ujung yang runcing, dan 'tumpul' dengan kesan berat dan lebar (kata 'tumpul' terdengar lebih besar dan lebih lambat diucapkan, seperti sudut lebar yang digambarkannya) — menggunakan trik asosiasi kata yang mudah diingat seperti ini membantu membuat pasangan istilah kosakata yang terasa sembarang jadi lebih melekat, alih-alih hanya menghafal 'lancip=kecil, tumpul=besar' tanpa jangkar."},
{n:78,type:"mcq",micro:"Mengenali hasil yang tidak mungkin",q:"Kamu diberitahu bahwa ketiga sudut dalam segitiga yang dihitung adalah 90°, 100°, dan 20°. Apakah ini segitiga yang valid?",options:["Ya, ini segitiga yang valid, karena 90° + 100° + 20° dapat dipakai bila salah satu sudutnya dibulatkan ke angka terdekat","Tidak — ketiga sudut ini berjumlah 210°, bukan 180°, jadi kombinasi ini tidak mungkin untuk segitiga nyata mana pun","Ya, ini segitiga valid, karena jumlah sudut segitiga boleh lebih dari 180°"],answer:1,explain:"90+100+20=210°, yang tidak sama dengan 180°, jadi ketiga sudut ini tidak bisa membentuk segitiga yang valid — pemeriksaan hasil-tidak-mungkin yang genuine.",hint:"Apakah ketiga sudut yang diberikan ini benar-benar berjumlah total segitiga yang dibutuhkan, 180°?"},
{n:79,type:"open",micro:"Merancang sistem berbasis sudut yang adil",q:"Rancang cara sederhana bagi kelas pertukangan kayu sekolah untuk membantu siswa menghindari kesalahan pemotongan sudut saat membangun bingkai foto kayu dengan sudut miring (bersudut).",explain:"Sistem hitung-lalu-verifikasi-sebelum-memotong yang jelas adalah cara yang benar-benar praktis untuk mencegah kesalahan pemotongan sudut dunia nyata yang umum dan mahal.",hint:"Akankah menghitung dan memverifikasi setiap sudut pemotongan SEBELUM memotong (alih-alih menaksirnya dengan mata selama pemotongan) membantu mencegah kesalahan sudut yang tidak cocok yang mahal?",sample:"Minta siswa menghitung dan dengan jelas menuliskan setiap sudut pemotongan yang dibutuhkan SEBELUM menyentuh gergaji (menggunakan aturan bahwa sudut-sudut bingkai yang berdekatan harus berjumlah 180° agar potongannya pas rata), lalu memeriksa ulang setiap sudut yang dihitung dengan busur derajat sungguhan atau panduan sudut terhadap garis potong yang ditandai sebelum memotong, alih-alih hanya memperkirakan sudutnya dengan mata selama proses pemotongan itu sendiri."},
{n:80,type:"mcq",micro:"Pemeriksaan keyakinan sudut",q:"Kamu menghitung sudut yang hilang pada garis lurus (dengan sudut yang diketahui 112°) tiga kali terpisah dan mendapat 68°, 68°, dan 292°. Apa kesimpulan yang paling masuk akal?",options:["Nilai sebenarnya adalah 78°, karena itu angka terbesar dari ketiga percobaan dan paling lengkap hitungannya sehingga paling dapat dipercaya","Tidak ada dari ketiga percobaan yang bisa dipercaya, sehingga sudut yang hilang harus diukur dengan busur derajat di gambar","Nilai sebenarnya sangat mungkin 68°, karena cocok dengan dua dari tiga percobaan (dan dengan benar berjumlah 180° dengan 112°)"],answer:2,explain:"Ketika sebagian besar percobaan berulang cocok (dua dari tiga mendapat 68°), dan nilai itu dengan benar berjumlah 180° dengan sudut yang diketahui, itu adalah hasil yang bisa dipercaya (292° kemungkinan berasal dari menjumlahkan alih-alih mengurangi).",hint:"Jawaban mana yang muncul lebih sering di antara ketiga percobaanmu, dan apakah dengan benar berjumlah 180° dengan 112°?"},
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah tangga bersandar pada dinding, membentuk sudut 65° dengan tanah. Sudut apa yang dibentuk tangga itu dengan DINDING (dengan asumsi dindingnya benar-benar vertikal, membentuk sudut siku-siku dengan tanah)? Tunjukkan penalaranmu.",explain:"Penerapan langsung aturan jumlah sudut segitiga pada skenario keamanan/geometri yang benar-benar berdasar fisik nyata.",hint:"Pikirkan tangga, tanah, dan dinding sebagai membentuk segitiga — gunakan fakta bahwa ketiga sudut segitiga siku-siku harus berjumlah 180°.",sample:"Tangga, tanah, dan dinding membentuk segitiga siku-siku di mana sudut tanah-dinding adalah 90°; karena ketiga sudut segitiga harus berjumlah 180°, dan sudut tangga-tanah adalah 65°, sudut tangga-dinding=180−90−65=25° — ditemukan dengan menerapkan aturan jumlah sudut segitiga pada skenario tangga bersandar nyata ini."},
{n:82,type:"open",micro:"Merancang pemeriksaan pengukuran berbasis sudut nyata",q:"Kamu ingin memeriksa apakah rak buku yang kamu bangun benar-benar memiliki sudut siku-siku (90°) sejati, hanya menggunakan selembar kertas (tanpa busur derajat). Jelaskan metode menggunakan lipatan sudut.",explain:"Menerapkan penalaran pembagian-dua/lipat sudut nyata pada skenario verifikasi-pengukuran yang benar-benar praktis dan bebas-alat.",hint:"Bisakah melipat strip kertas lurus (180°) menjadi dua menciptakan sudut referensi 90° yang andal untuk dibandingkan?",sample:"Lipat selembar kertas menjadi dua kali (setiap lipatan membagi dua sudutnya: tepi rata penuh adalah 180°, dilipat sekali memberikan sudut 90°) untuk membuat sudut referensi 90° yang andal, lalu tahan sudut kertas yang dilipat itu di setiap sudut rak buku — jika tepi kertas itu sejajar rata terhadap sudut rak tanpa celah di kedua sisi, sudut rak itu adalah sudut siku-siku sejati."},
{n:83,type:"open",micro:"Menyelidiki klaim sudut yang tidak konsisten",q:"Sebuah panduan perakitan furnitur mengklaim sandaran kursi diatur pada 'tepat 105°,' tetapi ketika kamu mengukurnya sendiri dengan busur derajat, kamu mendapat 98°. Bagaimana kamu akan menyelidiki perbedaan ini dengan jujur?",explain:"Mengenali dan dengan jujur menyelidiki perbedaan sudut nyata, alih-alih mengasumsikan salah satu angka otomatis benar atau salah, mencerminkan penalaran matang tentang klaim sudut dalam produk manufaktur nyata.",hint:"Bisakah sudut desain yang dinyatakan produsen sedikit berbeda dari sudut sebenarnya yang terpasang pada satu unit nyata tertentu, karena variasi manufaktur normal?",sample:"Periksa ulang pengukuranmu sendiri dengan hati-hati (memastikan titik pusat busur derajat dan garis 0°-nya sejajar dengan benar dengan titik putar sandaran sebenarnya dan garis dudukan), dan pertimbangkan bahwa angka panduan itu mungkin menggambarkan spesifikasi DESAIN (bagaimana itu dimaksudkan untuk diproduksi) alih-alih sudut sebenarnya yang terpasang pada unit spesifik ini, yang bisa sedikit bervariasi karena toleransi manufaktur normal — alih-alih mengasumsikan salah satu angka otomatis salah."},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) bagaimana pengukuran sudut secara historis penting dalam bidang seperti navigasi (menggunakan sudut ke bintang) atau astronomi/arsitektur kuno. Jelaskan singkat apa yang kamu temukan.",explain:"Menghubungkan pengukuran sudut dengan kepentingan sejarah nyatanya dalam navigasi dan astronomi/arsitektur kuno menunjukkan relevansi skill ini yang lebih luas di dunia nyata.",hint:"Mengapa mengukur sudut ke bintang secara presisi mungkin penting bagi pelaut historis yang mencoba mencari tahu lokasi kapalnya di laut?",sample:"Secara historis, pelaut menggunakan pengukuran sudut (seperti sudut antara horizon dan bintang, menggunakan alat seperti astrolab atau kemudian sekstan) untuk membantu menentukan posisi kapal mereka di laut, dan astronom serta arsitek kuno menggunakan perhitungan sudut yang hati-hati untuk menyelaraskan struktur dengan peristiwa langit (seperti titik balik matahari) atau membangun monumen yang stabil dan simetris — menunjukkan bahwa pengukuran sudut yang presisi memiliki kepentingan praktis yang nyata dan bertaruhan tinggi selama ribuan tahun, bukan hanya topik kelas matematika modern."},
{n:85,type:"open",micro:"Masalah pengukuran nyata multi-langkah",q:"Tali layang-layang membentuk sudut 40° dengan tanah. Jika layang-layang itu tepat di atas titik yang berjarak 30 meter dari tempatmu berdiri (diukur di sepanjang tanah), bagaimana kira-kira kamu akan bernalar tentang panjang tali sebenarnya yang lebih panjang dari 30 meter?",explain:"Menerapkan penalaran berbasis sudut tentang panjang sisi segitiga pada skenario geometri yang nyata dan secara fisik intuitif, tanpa membutuhkan trigonometri formal.",hint:"Dalam segitiga siku-siku, apakah sisi yang berlawanan dengan sudut siku-siku (sisi terpanjang) selalu akan lebih panjang daripada kedua sisi lebih pendek lainnya?",sample:"Karena tali membentuk sisi terpanjang (hipotenusa) dari segitiga siku-siku di mana jarak tanah 30 m adalah satu sisi yang lebih pendek, dan sudut antara tali dan tanah (40°) kurang dari 90°, tali itu sendiri harus LEBIH PANJANG dari jarak tanah 30 m — bernalar tentang sisi mana dari segitiga siku-siku yang paling panjang, berdasarkan ukuran sudutnya, bahkan tanpa melakukan perhitungan trigonometri yang tepat, menunjukkan pemahaman geometris yang genuine tentang hubungan sudut-sisi."},
{n:86,type:"open",micro:"Refleksi kesalahan sudut",q:"Ceritakan saat nyata (dalam skill ini atau dalam kehidupan nyata) ketika kamu membuat kesalahan dengan sudut — seperti membingungkan lancip dan tumpul, menggunakan total jumlah-sudut yang salah (180° vs 360°), atau salah membaca busur derajat. Apa penyebabnya, dan apa yang akan kamu lakukan berbeda sekarang?",explain:"Merenungkan kesalahan sudut pribadi yang nyata, dengan perbaikan konkret, menunjukkan skill ini sudah benar-benar tertanam.",hint:"Ingat kembali momen ketika perhitungan atau pembacaan sudut ternyata salah — apa tepatnya yang salah dalam langkahmu?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti membingungkan skala busur derajat mana yang dibaca, mencampuradukkan total garis-lurus 180° vs putaran-penuh 360°, atau salah melabeli sudut tumpul sebagai lancip) dan menyebutkan perbaikan konkret, seperti selalu memeriksa ulang hubungan mana yang berlaku dulu, atau memverifikasi pembacaan busur derajat terhadap perkiraan visual cepat."},
{n:87,type:"open",micro:"Merancang proyek sudut kelas",q:"Rancang proyek kelas sederhana bagi 30 siswa untuk mempraktikkan pengukuran sudut nyata — seperti mengukur sudut nyata yang ditemukan di sekitar kelas (sudut, tanjakan, pintu terbuka) dengan busur derajat.",explain:"Ini adalah sistem praktis dan langsung untuk andal mempraktikkan pengukuran dan klasifikasi sudut nyata menggunakan benda dunia nyata yang genuine dan bersama.",hint:"Akankah beberapa kelompok mengukur sudut nyata yang SAMA (seperti pintu atau tanjakan yang sama), lalu membandingkan hasil, membantu siswa menangkap dan memahami ketidakkonsistenan pengukuran?",sample:"Minta siswa bekerja dalam kelompok kecil untuk menemukan dan mengukur 5 sudut nyata berbeda di sekitar kelas atau sekolah (seperti pintu yang terbuka pada berbagai titik, kemiringan tanjakan, atau rambu segitiga), catat setiap pengukuran dengan busur derajat, klasifikasikan masing-masing sebagai lancip/siku-siku/tumpul/refleks, lalu bandingkan temuan mereka dengan kelompok lain yang mengukur benda yang sama untuk memeriksa konsistensi pengukuran."},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi jumlah sudut",q:"Perkirakan total ketiga sudut dalam segitiga yang kamu sketsa dengan bebas tangan (tanpa busur derajat) dengan membandingkan setiap sudut secara visual dengan sudut siku-siku, lalu jelaskan bagaimana kamu akan memverifikasi perkiraanmu.",explain:"Ini menerapkan teknik 'perkirakan setiap bagian dengan membandingkan dengan referensi yang diketahui (sudut siku-siku), lalu verifikasi dengan pengukuran tepat' pada skenario sudut-segitiga yang nyata.",hint:"Bisakah membandingkan setiap sudut dengan referensi yang diketahui (sudut siku-siku) memberikan perkiraan kasar yang masuk akal sebelum pengukuran busur derajat yang tepat?",sample:"Perkiraan visual cepat: menilai setiap sudut sebagai kira-kira 'sedikit kurang dari sudut siku-siku,' 'sekitar setengah sudut siku-siku,' dan 'sedikit lebih dari sudut siku-siku' mungkin memberikan perkiraan jumlah kasar yang dekat dengan 180°; kamu bisa memverifikasi ini dengan mengukur setiap sudut secara presisi dengan busur derajat sungguhan dan menjumlahkan ketiga pengukuran tepatnya, memeriksa bahwa total tepatnya memang 180° (atau sangat dekat, memperhitungkan sedikit ketidaktepatan menggambar tangan)."},
{n:89,type:"open",micro:"Menyelidiki perbedaan nyata (alat ukur)",q:"Kamu mengukur sudut dunia nyata yang sama (seperti kemiringan tanjakan) dengan busur derajat fisik dan aplikasi pengukur sudut bawaan smartphone, dan mendapat 18° dan 21°. Berikan dua kemungkinan penjelasan berbeda untuk perbedaan ini, dan bagaimana kamu akan menyelidiki masing-masing.",explain:"Mempertimbangkan beberapa penyebab yang mungkin untuk perbedaan alat pengukuran dunia nyata, dan cara mengujinya, mencerminkan penalaran investigatif yang genuine tentang presisi pengukuran sudut.",hint:"Bisakah perbedaan itu berasal dari seberapa hati-hati busur derajat fisik disejajarkan, atau dari batasan kalibrasi sensor smartphone itu sendiri?",sample:"Kemungkinan 1: busur derajat fisik mungkin tidak dipegang benar-benar diam atau sejajar tepat di sepanjang garis kemiringan sebenarnya tanjakan itu, menyebabkan sedikit kesalahan pembacaan — ukur ulang dengan hati-hati, memastikan tepi lurus busur derajat sejajar rata terhadap tanjakan itu. Kemungkinan 2: aplikasi smartphone mungkin mengandalkan sensor internal ponsel, yang bisa memiliki kesalahan kalibrasi kecil sendiri atau terpengaruh oleh bagaimana ponsel itu sendiri dipegang terhadap permukaan — periksa informasi akurasi/kalibrasi yang dinyatakan aplikasi itu, atau coba kalibrasi ulang."},
{n:90,type:"open",micro:"Koneksi sudut dan statistik",q:"Sebuah laporan menyatakan 'rata-rata sudut kemiringan atap di suatu lingkungan adalah 30°.' Mengapa satu angka sudut rata-rata ini mungkin tidak memberitahumu banyak tentang atap rumah TERTENTU mana pun di lingkungan itu?",explain:"Ini menghubungkan pemahaman sudut langsung dengan menafsirkan rata-rata statistik nyata dengan benar dan batasannya.",hint:"Apakah mengetahui HANYA kemiringan atap rata-rata memberitahumu rentang sudut atap individual sebenarnya di lingkungan itu?",sample:"Rata-rata menggabungkan banyak sudut atap individual berbeda menjadi satu angka ringkasan — beberapa atap bisa jauh lebih datar (seperti 15°) dan yang lain jauh lebih curam (seperti 45°), dengan rata-rata 30° belum tentu cocok dekat dengan atap individual khas mana pun, menunjukkan mengapa satu sudut rata-rata tidak mengungkapkan rentang atau variasi sebenarnya di antara atap nyata di lingkungan itu."},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan hitung skenario berbasis sudut nyata (seperti menemukan sudut yang hilang dalam segitiga nyata, soal sudut garis lurus, atau mengukur kemiringan dunia nyata), menunjukkan pekerjaanmu dengan jelas. Laporkan hasil dan metodemu.",explain:"Ini adalah penerapan kapstone langsung dari keterampilan sudut pada tugas nyata yang kamu rancang sendiri.",hint:"Akankah menunjukkan setiap langkah perhitungan sudut dengan jelas (bukan hanya jawaban akhir) membuat pekerjaanmu lebih mudah diperiksa dan dipercaya orang lain?",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan operasi sudut nyata (mengukur dengan busur derajat, menerapkan hubungan jumlah-sudut yang diketahui, atau mengklasifikasikan jenis sudut) dalam skenario realistis yang kamu rancang sendiri."},
{n:92,type:"open",micro:"Menjelaskan sudut ke anak yang jauh lebih muda",q:"Bagaimana kamu akan menjelaskan apa itu sudut kepada anak yang belum pernah melihat istilah ini, menggunakan sesuatu yang mereka pahami?",explain:"Menyederhanakan konsep geometris abstrak menggunakan contoh yang konkret dan relevan menunjukkan pemahaman yang mendalam dan bisa dipindahkan.",hint:"Benda sehari-hari apa yang terbuka dan tertutup (seperti pintu) yang akan membantu menjelaskan apa yang sebenarnya diwakili sebuah sudut?",sample:"Saya akan menggunakan pintu nyata — 'ketika kamu membuka pintu hanya sedikit, ruang antara pintu dan dinding adalah sudut kecil; ketika kamu mengayunkannya terbuka sangat lebar, ruang itu menjadi sudut besar — sudut hanyalah seberapa banyak sesuatu telah 'terbuka' atau 'berputar' dari posisi awalnya, dan kita bisa mengukur persis berapa banyak dengan alat khusus yang disebut busur derajat.'"},
{n:93,type:"open",micro:"Refleksi",q:"Menurutmu mengapa memulai dengan pengalaman sudut fisik nyata (seperti membuka pintu atau membandingkan kecuraman tanjakan) begitu penting sebelum melanjutkan ke aturan dan rumus jumlah-sudut abstrak?",explain:"Ini mencerminkan wawasan nyata tentang mengapa perjalanan Konkret-Piktorial-Abstrak sangat penting khususnya untuk sudut, skill yang sering diajarkan sebagai hafalan rumus murni tanpa dasar konseptual nyata.",hint:"Akankah aturan jumlah-sudut abstrak lebih masuk akal bagi seseorang yang telah secara fisik mengalami membandingkan jumlah 'bukaan' atau 'putaran' berbeda, atau bagi seseorang yang hanya menghafal rumusnya?",sample:"Tanpa dulu merasakan apa yang sebenarnya diwakili sudut melalui tindakan fisik nyata (membuka pintu lebih lebar vs lebih sempit, membandingkan tanjakan curam vs landai), aturan abstrak (seperti 'sudut pada garis lurus berjumlah 180°') bisa terasa seperti fakta sembarang untuk dihafal alih-alih sesuatu yang menggambarkan jumlah putaran atau bukaan nyata dan bermakna — membangun dari pengalaman sudut konkret dan nyata dulu membantu aturan dan hubungan abstrak benar-benar masuk akal secara konseptual nanti."},
{n:94,type:"open",micro:"Keputusan bisnis menggunakan sudut",q:"Sebuah perusahaan pemasangan panel surya menemukan bahwa menyesuaikan sudut kemiringan panel secara musiman (alih-alih menetapkannya pada satu sudut sepanjang tahun) bisa meningkatkan penangkapan energi, tetapi membutuhkan suku cadang mekanis dan perawatan ekstra. Keputusan bisnis apa yang mungkin didukung trade-off berbasis sudut ini, dan apa yang masih perlu diwaspadai perusahaan itu?",explain:"Menerapkan penalaran berbasis sudut pada keputusan trade-off bisnis nyata, menimbang potensi keuntungan efisiensi melawan biaya dan kompleksitas tambahan.",hint:"Apakah strategi penyesuaian sudut yang secara teknis 'lebih baik' otomatis berarti itu pilihan bisnis yang tepat untuk setiap situasi pelanggan tunggal?",sample:"Mereka mungkin menawarkan penyesuaian musiman sebagai opsi premium bagi pelanggan yang ingin efisiensi energi maksimum dan bersedia membayar untuk kompleksitas mekanis dan perawatan ekstra, sambil tetap menawarkan opsi sudut-tetap yang lebih sederhana dan lebih murah untuk pelanggan yang mengutamakan biaya rendah dan perawatan minimal — tetapi tetap harus waspada apakah keuntungan energi sebenarnya dari penyesuaian musiman cukup besar, untuk lokasi dan anggaran pelanggan tertentu, untuk benar-benar membenarkan biaya dan kompleksitas tambahan."},
{n:95,type:"open",micro:"Sudut bertemu keadilan (membagi sumber daya bundar)",q:"Empat teman ingin membagi pizza bundar menjadi empat potongan yang mencerminkan berapa banyak setiap orang membayar (bukan seperempat yang sama persis): Rp30.000, Rp20.000, Rp15.000, dan Rp15.000 dari total Rp80.000. Jelaskan bagaimana sudut mengelilingi titik (360°) membantu menjamin pembagian yang adil berdasarkan pembayaran.",explain:"Menghubungkan aturan sudut-mengelilingi-titik langsung dengan diskusi keadilan nyata tentang membagi sumber daya bundar bersama berdasarkan kontribusi tidak sama.",hint:"Akankah membagi pizza menjadi empat potongan 90° yang persis sama secara adil mencerminkan fakta bahwa keempat teman membayar jumlah yang sangat berbeda?",sample:"Bagian sudut setiap orang ditemukan dengan pecahan pembayaran mereka dari total, dikalikan dengan 360°: Rp30.000/80.000×360°=135°, Rp20.000/80.000×360°=90°, dan masing-masing Rp15.000/80.000×360°=67,5° — menggunakan bagian sudut berbasis-pembayaran ini (alih-alih empat potongan sama 90°) menjamin ukuran potongan setiap teman secara adil mencerminkan berapa banyak yang sebenarnya mereka kontribusikan."},
{n:96,type:"open",micro:"Batasan statistik sudut",q:"Sebuah laporan menyatakan 'balok penyangga jembatan ini diatur pada sudut struktural 60°.' Apa yang bisa diberitahukan angka sudut ini, dan apa yang tidak bisa diberitahukannya sendiri?",explain:"Mengenali bahwa statistik sudut memberikan detail spesifik yang berguna, tetapi tidak otomatis konteks teknik penuh yang dibutuhkan untuk menilai kesesuaiannya, adalah koneksi berpikir kritis yang penting.",hint:"Apakah mengetahui HANYA sudut balok penyangga memberitahumu apakah sudut spesifik itu sebenarnya aman dan tepat untuk kebutuhan teknik penuh jembatan tertentu ini?",sample:"Ini bisa memberitahumu detail desain spesifik tentang bagaimana balok penyangga itu disudutkan — tetapi tidak bisa memberitahumu sendiri apakah sudut itu sebenarnya tepat atau aman untuk ukuran, bahan, dan kebutuhan beban jembatan SPESIFIK ini, karena sudut yang tepat untuk balok penyangga bergantung pada banyak faktor teknik lain di luar sekadar angka sudutnya sendiri, jadi satu angka sudut tidak menangkap gambaran teknik penuh."},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk mengetahui, menggunakan pengukuran sudut, kira-kira seberapa 'bisa dilalui' atau 'bisa diakses kursi roda' sekumpulan tanjakan di sekitar sekolah atau lingkunganmu, tanpa membutuhkan peralatan survei profesional.",explain:"Menerapkan strategi 'ukur dengan alat yang mudah diakses, bandingkan dengan patokan yang diketahui, ringkas secara praktis' pada tugas investigasi-aksesibilitas dunia nyata yang benar-benar praktis.",hint:"Akankah mengukur sudut setiap tanjakan dengan busur derajat sederhana atau aplikasi, lalu membandingkan dengan patokan keamanan yang diketahui, memberikan gambaran praktis yang berguna tanpa membutuhkan peralatan profesional?",sample:"Gunakan busur derajat sederhana (atau aplikasi sudut smartphone) untuk mengukur sudut kemiringan setiap tanjakan, bandingkan setiap sudut yang diukur dengan sudut maksimum tanjakan-bisa-diakses yang umum direkomendasikan (patokan keamanan yang wajar), dan buat daftar atau peta sederhana yang mencatat tanjakan mana yang terlihat cukup landai versus mana yang terlihat luar biasa curam, alih-alih mencoba mencapai presisi survei tingkat profesional untuk setiap tanjakan tunggal."},
{n:98,type:"open",micro:"Sudut dan teknologi",q:"Banyak aplikasi dan perangkat (seperti aplikasi pengukur sudut smartphone, kontrol kamera video game, atau perangkat lunak lengan robotik) secara otomatis menghitung dan menampilkan sudut secara real-time. Apa satu keuntungan dan satu risiko dari sepenuhnya mempercayai tampilan sudut otomatis semacam ini?",explain:"Memperluas penalaran sudut ke alat digital nyata, menimbang kenyamanan tampilan real-time otomatis melawan risiko tidak memahami persis apa yang diukur atau seberapa andal.",hint:"Apakah pembacaan sudut yang ditampilkan otomatis selalu datang dengan jaminan bahwa sensor yang mendasarinya dikalibrasi dengan benar dan akurat?",sample:"Keuntungan: alat-alat ini bisa secara instan menampilkan pengukuran sudut yang presisi dalam situasi di mana pengukuran manual akan lambat, sulit, atau tidak mungkin (seperti sudut sendi real-time lengan robotik). Risiko: mempercayai buta sudut yang ditampilkan tanpa memahami apa yang sebenarnya diukurnya (seperti apakah sensor aplikasi smartphone dikalibrasi dengan benar, atau titik referensi tepat apa yang diukurnya) bisa menyebabkan ketidakcocokan dunia nyata antara angka yang ditampilkan dan sudut fisik sebenarnya."},
{n:99,type:"open",micro:"Menyelidiki angka sudut yang bertentangan",q:"Dua laporan teknik berbeda memberikan angka yang sedikit berbeda untuk sudut penyangga kabel jembatan yang sama (seperti 42° versus 44°). Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan seperti ini?",explain:"Menerapkan penalaran yang matang, skeptis namun adil, pada angka sudut teknik yang tampak bertentangan, menghindari kepercayaan buta maupun tuduhan yang tidak adil.",hint:"Bisakah dua laporan teknik benar-benar sedikit berbeda tentang sudut struktur besar karena titik referensi atau metode pengukuran berbeda, bukan karena salah satu membuat kesalahan?",sample:"Pembaca yang cermat sebaiknya menyadari bahwa mengukur sudut struktur nyata berskala besar bisa benar-benar sedikit berbeda berdasarkan tepat titik referensi mana yang digunakan, metode atau peralatan pengukuran, atau bahkan sedikit variasi dunia nyata di berbagai titik sepanjang struktur, alih-alih mengasumsikan satu laporan sekadar membuat kesalahan, dan sebaiknya melihat bagaimana setiap laporan menggambarkan metode pengukuran spesifik dan titik referensinya sebelum memutuskan angka mana yang dipercaya untuk tujuan tertentu."},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali skill Sudut ini — mulai dari tindakan fisik nyata seperti membuka pintu atau membandingkan kecuraman tanjakan, ke gambar busur derajat dan diagram berlabel, dan akhirnya ke aturan jumlah-sudut abstrak dan penalaran dunia nyata — kebiasaan apa yang sekarang kamu miliki saat melihat atau mengerjakan sudut?",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa skill ini sudah tertanam.",hint:"Pikirkan momen dalam unit ini ketika sudut berhenti membutuhkan gambar atau perbandingan pintu/tanjakan fisik dan mulai masuk akal sebagai pengukuran abstrak dengan sendirinya.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis memeriksa hubungan sudut mana yang berlaku (garis lurus 180°, putaran penuh 360°, atau segitiga 180°) sebelum menghitung, memeriksa ulang pembacaan busur derajat terhadap perkiraan visual cepat, atau lebih berhati-hati membedakan sudut lancip, tumpul, dan refleks alih-alih hanya menebak dengan mata."},
];
